# Write only explicit user-selected files; replacement is atomic in the same directory.
import json
import os
import tempfile
from pathlib import Path

def write_json(path, value):
    target = Path(path)
    handle, temporary = tempfile.mkstemp(prefix='.'+target.name+'.',suffix='.tmp',dir=target.parent)
    try:
        with os.fdopen(handle,'w',encoding='utf-8') as stream:
            json.dump(value,stream,ensure_ascii=False,indent=2)
            stream.write('\n')
        os.replace(temporary,target)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)

def read_json(path):
    if Path(path).stat().st_size > 2*1024*1024:
        raise ValueError('Project data must be at most 2 MB.')
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))

# Cards belong to one of three stages. Dates are ISO YYYY-MM-DD or empty.
from datetime import date
import time
import uuid
STAGES = ('To do','In progress','Done')

def kanban_validate(value):
    if not isinstance(value,dict) or value.get('type') != 'tkvf-kanban' or value.get('version') != 1:
        raise ValueError('This is not a Kanban v1 file.')
    cards = value.get('cards')
    if not isinstance(cards,list) or len(cards) > 120:
        raise ValueError('At most 120 cards are supported.')
    ids = set()
    for card in cards:
        if not isinstance(card,dict) or set(card) != {'id','title','due','stage'}:
            raise ValueError('Invalid card fields.')
        if not all(isinstance(v,str) for v in card.values()):
            raise ValueError('Card fields must be text.')
        if not card['id'] or len(card['id']) > 50 or card['id'] in ids or not card['title'].strip() or len(card['title']) > 160 or card['stage'] not in STAGES:
            raise ValueError('Invalid card or duplicate ID.')
        ids.add(card['id'])
        if card['due']:
            if date.fromisoformat(card['due']).isoformat() != card['due']:
                raise ValueError('Use YYYY-MM-DD for dates.')
    return [dict(card) for card in cards]

def kanban_draw(app):
    c = app.Board; c.delete('all'); app.card_rects = []
    counts = [0,0,0]
    for i,stage in enumerate(STAGES):
        c.create_rectangle(i*310,0,(i+1)*310-10,14000,fill=('#eef3fb','#fff5d8','#e4f4eb')[i],outline='')
        c.create_text(i*310+12,18,text=stage,anchor='w',font=('TkDefaultFont',13,'bold'))
    today = date.today().isoformat()
    for card in app.cards:
        column = STAGES.index(card['stage']); y = 45+counts[column]*75; counts[column] += 1; x = column*310+10
        app.card_rects.append((x,y,x+280,y+65,card['id']))
        c.create_rectangle(x,y,x+280,y+65,fill='white',outline='#3476bf' if card['id']==app.selected else '#b6c3d1',width=2)
        c.create_text(x+8,y+8,text=card['title'],anchor='nw',width=260)
        overdue = card['due'] and card['due'] < today and card['stage'] != 'Done'
        c.create_text(x+8,y+52,text=('Overdue: ' if overdue else 'Due: ')+card['due'] if card['due'] else 'No due date',anchor='w',fill='#b02d2d' if overdue else '#52627a')
    c.configure(scrollregion=(0,0,930,max(390,50+max(counts)*75)))
    app.Summary.configure(text=f'{len(app.cards)} tasks | Done: {counts[2]} | Focus sessions: {app.focus_sessions} | '+('Unsaved changes' if app.dirty else 'Saved / new'))

def kanban_select(app,event):
    x,y = app.Board.canvasx(event.x),app.Board.canvasy(event.y); app.dragging = None
    for left,top,right,bottom,identifier in app.card_rects:
        if left <= x <= right and top <= y <= bottom:
            app.selected = identifier; app.dragging = identifier
            card = next(c for c in app.cards if c['id']==identifier)
            app.Title.delete(0,'end'); app.Title.insert(0,card['title']); app.Due.delete(0,'end'); app.Due.insert(0,card['due']); app.Stage.set(card['stage'])
            break
    kanban_draw(app)

def kanban_drag(app,event):
    if app.dragging:
        app.Board.configure(cursor='fleur')

def kanban_release(app,event):
    app.Board.configure(cursor='')
    identifier = app.dragging; app.dragging = None
    if identifier and 0 <= event.x < 930 and 0 <= event.y < 390:
        card = next(c for c in app.cards if c['id']==identifier)
        stage = STAGES[min(2,int(app.Board.canvasx(event.x)//310))]
        if card['stage'] != stage:
            card['stage'] = stage; app.Stage.set(stage); app.dirty = True
        kanban_draw(app)

def kanban_edit(app, update=False):
    try:
        if update and not app.selected:
            raise ValueError('Select a card first.')
        card = {'id':app.selected if update else uuid.uuid4().hex,'title':app.Title.get().strip(),'due':app.Due.get().strip(),'stage':app.Stage.get()}
        cards = [card if old['id']==card['id'] else dict(old) for old in app.cards] if update else app.cards+[card]
        cards = kanban_validate({'type':'tkvf-kanban','version':1,'cards':cards})
        app.cards = cards; app.selected = card['id']; app.dirty = True; kanban_draw(app)
    except (ValueError,TypeError) as exc:
        messagebox.showerror('Kanban',str(exc),parent=app.Form1)

def kanban_delete(app):
    if app.selected and messagebox.askyesno('Kanban','Delete the selected task?',parent=app.Form1):
        app.cards = [c for c in app.cards if c['id']!=app.selected]; app.selected = None; app.dirty = True; kanban_draw(app)

def kanban_file(app, opening=False):
    if opening and app.dirty and not messagebox.askyesno('Kanban','Discard unsaved board changes?',parent=app.Form1):
        return
    path = (filedialog.askopenfilename if opening else filedialog.asksaveasfilename)(parent=app.Form1,defaultextension='.json',filetypes=[('Kanban JSON','*.json')])
    if not path:
        return
    try:
        if opening:
            cards = kanban_validate(read_json(path)); app.cards = cards; app.selected = None; app.dragging = None
        else:
            write_json(path,{'type':'tkvf-kanban','version':1,'cards':app.cards})
        app.dirty = False; kanban_draw(app)
    except (OSError,ValueError,TypeError) as exc:
        messagebox.showerror('Kanban',str(exc),parent=app.Form1)

def focus_pause(app):
    if app.focus_running:
        app.focus_remaining = max(0,app.focus_deadline-time.monotonic())
    app.focus_running = False; app.focus_generation += 1
    if app.focus_timer is not None:
        app.root.after_cancel(app.focus_timer); app.focus_timer = None

def focus_tick(app,generation):
    if not app.focus_running or generation != app.focus_generation:
        return
    app.focus_timer = None; app.focus_remaining = max(0,app.focus_deadline-time.monotonic())
    seconds = int(app.focus_remaining+0.999)
    app.TimerLabel.configure(text=f'Focus {seconds//60:02}:{seconds%60:02}')
    if app.focus_remaining <= 0:
        app.focus_running = False; app.focus_sessions += 1; app.TimerLabel.configure(text='Focus complete — take a short break.'); kanban_draw(app)
    else:
        app.focus_timer = app.root.after(200,lambda:focus_tick(app,generation))

def focus_start(app):
    if app.focus_running:
        return
    if app.focus_remaining <= 0:
        try:
            minutes = int(app.Minutes.get())
            if not 1 <= minutes <= 180:
                raise ValueError('Choose 1-180 minutes.')
            app.focus_remaining = minutes*60
        except ValueError as exc:
            messagebox.showerror('Pomodoro',str(exc),parent=app.Form1); return
    app.focus_deadline = time.monotonic()+app.focus_remaining; app.focus_running = True; app.focus_generation += 1; focus_tick(app,app.focus_generation)

def focus_reset(app):
    focus_pause(app); app.focus_remaining = 0; app.TimerLabel.configure(text='Focus ready; choose minutes then Start.')

def kanban_close(app):
    if app.dirty and not messagebox.askyesno('Kanban','Close and discard unsaved board changes?',parent=app.Form1):
        return
    focus_pause(app); app.root.destroy()
